import { FC, HTMLAttributes } from 'react';

import { Button, Dropdown } from 'antd';
import { MenuItemType } from 'antd/es/menu/interface';

import AngleIcon from 'assets/images/icons/angle-sort.svg?react';
import { EPaginationParams } from 'features/Pagination';
import { getValue } from 'features/Sort/utils/sort';
import { useCommonSlice, useSearchParamsWithHash } from 'shared/hooks';

interface ISortProps extends HTMLAttributes<HTMLDivElement> {
	sortItems: MenuItemType[];
	defaultSort?: MenuItemType;
}

export const Sort: FC<ISortProps> = ({
	className,
	sortItems,
	defaultSort = { key: 'created_at', label: 'Сначала старые' },
	...props
}) => {
	const [searchParams, setSearchParams] = useSearchParamsWithHash();
	const { clearInfinityScroll } = useCommonSlice();
	const selectedSort = sortItems?.find((item) => item?.key === getValue()) || defaultSort;

	const onSort = (sort: MenuItemType) => {
		searchParams.set('ordering', sort.key?.toString() || '');

		searchParams.delete(EPaginationParams.OFFSET);
		clearInfinityScroll();

		setSearchParams(searchParams);
	};

	return (
		<>
			<Dropdown
				{...props}
				className={className}
				menu={{ items: sortItems?.map((item) => ({ ...item, onClick: () => onSort(item) })) }}
				placement="bottomRight"
				trigger={['click']}>
				<Button variant="text" color="primary" size="small" icon={<AngleIcon />} iconPosition="end">
					{selectedSort.label}
				</Button>
			</Dropdown>
		</>
	);
};
